curl -s -X POST "https://slack.com/api/conversations.list" -d "token=<TOKEN>&types=public_channel&limit=100" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'deploy' in ch['name'].lower():
            print(f\"Channel: {ch['name']} ID: {ch['id']}\")
else:
    print(data)
"

curl -s -X POST "https://slack.com/api/search.messages" -d "token=<TOKEN>&query=rollback channel:C_DEPLOYS&count=50" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    messages = data.get('messages', {}).get('matches', [])
    for m in messages:
        print(f\"ts={m['ts']} user={m['user']} text={m['text']}\")
    if not messages:
        print('No messages found')
else:
    print(data)
"

curl -s -X POST "https://slack.com/api/conversations.history" -d "token=<TOKEN>&channel=C_DEPLOYS&limit=100" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    messages = data.get('messages', [])
    for m in messages:
        print(f\"ts={m['ts']} user={m.get('user','?')} text={m.get('text','')[:120]}\")
    if not messages:
        print('No messages found')
else:
    print(data)
"

curl -s -X POST "https://slack.com/api/users.list" -d "token=<TOKEN>" | python3 -c "
